world_checks.check_drafts_and_fixtures:
def check(world):
    state = world.state()
    labels = state.get("gmail_labels", [])
    if len(labels) < 5:
        return f"labels has {len(labels)} rows, expected at least 5"
    label_ids = {l["id"] for l in labels}
    tl = state.get("gmail_thread_labels", [])
    if not tl:
        return "thread_labels table is empty"
    for row in tl:
        if row["label_id"] not in label_ids:
            return f"invalid label_id {row['label_id']!r} in thread_labels"
    return None

world_checks.check_threads_and_messages:
def check(world):
    state = world.state()
    threads = state.get("gmail_threads", [])
    if len(threads) < 20:
        return f"threads has {len(threads)} rows, expected at least 20"
    messages = state.get("gmail_messages", [])
    if len(messages) < 20:
        return f"messages has {len(messages)} rows, expected at least 20"
    thread_ids = {t["id"] for t in threads}
    msg_thread_ids = {m["thread_id"] for m in messages}
    missing_msgs = thread_ids - msg_thread_ids
    if missing_msgs:
        return f"threads without messages: {missing_msgs}"
    orphans = msg_thread_ids - thread_ids
    if orphans:
        return f"messages in threads that do not exist: {sorted(orphans)}"
    # Conversations, not one message per thread: at least three threads carry a reply and a
    # follow-up, and a thread's updated_at is its latest message's date (search orders by it).
    by_thread = {}
    for m in messages:
        by_thread.setdefault(m["thread_id"], []).append(m)
    deep = [t for t, ms in by_thread.items() if len(ms) >= 3]
    if len(deep) < 3:
        return f"only {len(deep)} threads have three or more messages, expected at least 3"
    for t in threads:
        latest = max(m["date"] for m in by_thread.get(t["id"], []))
        if t["updated_at"] != latest:
            return f"thread {t['id']} updated_at {t['updated_at']} is not its latest message's date {latest}"
    clock = state.get("clock", [])
    if not clock or not clock[0].get("now"):
        return "clock table is empty or missing 'now'"
    return None
